entries[93433] = { ["name"] = "Bodenangriff", ["text"] = "10 Fokus und 5 pro Sek.\nKanalisiert (Wirken in 8 sek.) 14 sek. Abklingzeit\nDer Wurm gräbt sich in die Erde und erschüttert den Boden über ihm. Verursacht im Verlauf von 8 Sek. [( 77 + ((Fernkampfangriffskraft * 0.40) * 0.288)) * 8] Naturschaden." }
